(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.04+t*0.5)*8+Math.cos((y+w1y)*0.03-t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.04-t*0.45)*8+Math.sin((x+w1x)*0.035+t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.7],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.9],
    [80+Math.sin(t*0.7+3)*70,40+Math.cos(t*0.6+1)*50,0.14,2.1,0.6],
    [400+Math.cos(t*0.45+2)*60,220+Math.sin(t*0.65+4)*40,0.11,1.8,1.3]
  ];
  let aS=0,iS=0,harm=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=(Math.sin(d*f-t*sp)+Math.sin(d*f*1.618-t*sp*0.618+0.5)*0.3)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    harm+=Math.sin(d*f*0.5-t*sp*0.8+2.0)*amp*0.5;
  }
  const n=8,act=aS/n,inh=iS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+t*0.6)*Math.sin(sy*0.06-t*0.4)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.08-ang*2+t*0.8)*0.3;
  const lap=(bg+spiral)*0.5;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral+harm*0.2)*2.2);
  const rd2=Math.tanh((act-inh*0.7+bg*0.3+spiral+harm*0.15-lap*0.4)*1.8);
  const reaction=(rd1+rd2)*0.5;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.3)*0.3)*1.5)*0.3;
  const vortex=Math.sin(dist*0.03+ang*6-t*2)*Math.exp(-dist*0.008)*0.25;
  const blend=reaction*0.65+cell*0.25+vortex*0.1,v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,90],[18,85,120],[25,140,130],[60,185,140],[160,200,100],[220,190,70],[230,140,60],[210,90,65],[160,50,70],[80,25,65],[30,15,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const bright=1.0+(Math.abs(reaction)>0.75?0.18:0)+(Math.abs(reaction)>0.9?0.12:0);
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*bright)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*bright)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*bright)|0];
}
